{
  "headline": "FDA's records trace our supply to a plant classified OAI 1098 days before the posting",
  "headline_cites": ["D8"],
  "sentences": [
    {
      "text": "FDA first posted the valproate sodium shortage on 2020-12-30 and it remains Current as of 2026-10-21.",
      "cites": ["E32", "D9"]
    },
    {
      "text": "The shortage listing names Fresenius Kabi USA, LLC and Hikma Pharmaceuticals USA, Inc. as affected companies.",
      "cites": ["E30", "E31"]
    },
    {
      "text": "FDA's OAI classification letter to Fresenius Kabi USA, LLC is dated 2017-12-28, 1098 days before the shortage posting.",
      "cites": ["D8"]
    },
    {
      "text": "Fresenius Kabi USA, LLC also received a VAI classification 506 days before the posting and another VAI 299 days before the posting.",
      "cites": ["D6", "D7"]
    },
    {
      "text": "Hikma's manufacturing plant (FEI 3002807173) has an OAI inspection from 2014 and multiple VAI inspections through 2023.",
      "cites": ["E8", "E11", "E12", "E13"]
    },
    {
      "text": "Corvale East has 3.8 days of the 100 mg/mL 5 mL presentation on hand while Corvale General has 14.9 days.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The rule-ranked option is to transfer 3 vials of 100 mg/mL 5 mL from Corvale General to Corvale East, which would give Corvale East 5 days of supply while Corvale General retains two weeks.",
      "cites": ["D10"]
    }
  ]
}
